var n=`0777-mukeke`;var t=`world-0777`;var a=`BI`;var s=`eastern-africa`;var r=4;var o=62;var g={en:`Mukeke`,ua:`Мукеке`};var l={en:`Mukeke is a Burundi classic prepared with tilapia, lemon juice, garlic, yellow onion. A measured home-style version, with ingredients assigned to the cooking steps where they are used. Tilapia substitutes for the Burundian Lake Tanganyika mukeke fish species, absent from the catalog.`,ua:`Мукеке, страва кухні країни Бурунді зі складниками: тилапія, лимонний сік, часник, жовта цибуля. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування. Тіляпія замінює озерну рибу мукеке з Танганьїки, якої немає в каталозі.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 25 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 25 хвилин.`,t:[`marinating`],m:25,i:[[`tilapia`,830,`g`],[`lemon-juice`,55,`ml`],[`garlic`,4,`clove`],[`ground-cumin`,4,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,180,`g`],[`tomato`,300,`g`],[`sunflower-oil`,40,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 24 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 24 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:24,i:[[`water`,430,`ml`],[`green-bell-pepper`,180,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,18,`g`]]}];var m={slug:n,id:t,country:`BI`,region:s,servings:4,minutes:62,title:g,text:l,steps:u};export{a as country,m as default,t as id,o as minutes,s as region,r as servings,n as slug,u as steps,l as text,g as title};